class Solution {
  public int scoreDifference(int[] nums) {
    int diff = 0;
    boolean firstActive = true;
    for (int i = 0; i < nums.length; i++) {
      if (nums[i] % 2 == 1) firstActive = !firstActive;
      if (i % 6 == 5) firstActive = !firstActive;
      diff += firstActive ? nums[i] : -nums[i];
    }
    return diff;
  }
}
